"site_admin":false,"starred_url":"https://api.github.com/users/vc-ci/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/vc-ci/subscriptions","type":"User","url":"https://api.github.com/users/vc-ci","user_view_type":"public"},"comments_url":"https://api.github.com/repos/VirtoCommerce/vc-frontend/commits/2b75c7de79e676a7bad40f05487fb7ee3fb89cee/comments","commit":{"author":{"date":"2026-10-07T11:41:02Z","email":"ci@virtocommerce.com","name":"vc-ci"},"comment_count":0,"committer":{"date":"2026-10-07T11:41:02Z","email":"ci@virtocommerce.com","name":"vc-ci"},"message":"2.60.0","tree":{"sha":"219fcaf60e40deb02bbb883275d3eae4ec459970","url":"https://api.github.com/repos/VirtoCommerce/vc-frontend/git/trees/219fcaf60e40deb02bbb883275d3eae4ec459970"},"url":"https://api.github.com/repos/VirtoCommerce/vc-frontend/git/commits/2b75c7de79e676a7bad40f05487fb7ee3fb89cee","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/31079468?v=4","events_url":"https://api.github.com/users/vc-ci/events{/privacy}","followers_url":"https://api.github.com/users/vc-ci/followers","following_url":"https://api.github.com/users/vc-ci/following{/other_user}","gists_url":"https://api.github.com/users/vc-ci/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/vc-ci","id":31079468,"login":"vc-ci","node_id":"MDQ6VXNlcjMxMDc5NDY4","organizations_url":"https://api.github.com/users/vc-ci/orgs","received_events_url":"https://api.github.com/users/vc-ci/received_events","repos_url":"https://api.github.com/users/vc-ci/repos","site_admin":false,"starred_url":"https://api.github.com/users/vc-ci/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/vc-ci/subscriptions","type":"User","url":"https://api.github.com/users/vc-ci","user_view_type":"public"},"html_url":"https://github.com/VirtoCommerce/vc-frontend/commit/2b75c7de79e676a7bad40f05487fb7